def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = None

        # Split pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        # Version with prerelease sorts before version without
        # So we use (major, minor, patch, has_prerelease, prerelease_identifiers)
        # has_prerelease should be False (0) if prerelease exists, True (1) if not
        has_prerelease = len(prerelease_identifiers) == 0
        return (major, minor, patch, has_prerelease, prerelease_identifiers)

    return sorted(versions, key=sort_key)

